    void apply_tilt(int dir_idx) { 
        if (dir_idx == 0) { // F (Up)
            for (int c = 0; c < GRID_SIZE; ++c) {
                int current_write_r = 0;
                for (int r = 0; r < GRID_SIZE; ++r) {
                    if (board[r][c] != 0) {
                        if (r != current_write_r) {
                            board[current_write_r][c] = board[r][c];
                            board[r][c] = 0;
                        }
                        current_write_r++;
                    }
                }
            }
