    void rebuild_candies_list_from_board() {
        candies_list.clear(); 
        for (int r_idx = 0; r_idx < GRID_SIZE; ++r_idx) {
            for (int c_idx = 0; c_idx < GRID_SIZE; ++c_idx) {
                if (board[r_idx][c_idx] != 0) {
                    candies_list.push_back({r_idx, c_idx, board[r_idx][c_idx]});
                }
            }
        }
